type Customer = { id: number; firstName: string; lastName: string; email: string; active: boolean };
type DirectoryEntry = { id: number; displayName: string; email: string; active: boolean };
export function normalizeCustomers(customers: Customer[]): DirectoryEntry[] {
  const seen = new Set<number>();
  const result: DirectoryEntry[] = customers.map(customer => {
    if (!Number.isSafeInteger(customer.id) || !customer.firstName.trim() || !customer.lastName.trim() || !customer.email.trim().includes('@')) {
      throw new Error('Invalid customer');
    }
    if (seen.has(customer.id)) throw new Error('Duplicate id');
    seen.add(customer.id);
    return {
      id: customer.id,
      displayName: `${customer.firstName.trim()} ${customer.lastName.trim()}`,
      email: customer.email.trim().toLowerCase(),
      active: customer.active
    };
  });
  return result.sort((a,b) => a.id-b.id);
}
